21	func instanceJSON(instance store.Instance) gin.H {
22		return gin.H{
23			"service_name": instance.ServiceName,
24			"instance_id":  instance.InstanceID,
25			"address":      instance.Address,
26			"port":         instance.Port,
27			"healthy":      instance.Healthy,
28			"weight":       jsonWeight(instance.Weight),
29			"heartbeat_at": instance.HeartbeatAt.Format(time.RFC3339Nano),
30		}
31	}
