184	func TestDiscoverFiltersUnhealthyAndLostInstances(t *testing.T) {
185		router, st := testRouter(t)
186		registerInstance(t, router, map[string]any{
187			"service_name": "svc", "instance_id": "lost-old", "address": "a",
188			"healthy": true, "weight": 10, "heartbeat_at": at(0),
189		})
190		registerInstance(t, router, map[string]any{
191			"service_name": "svc", "instance_id": "fresh", "address": "b",
192			"healthy": true, "weight": 1, "heartbeat_at": at(9),
193		})
194		registerInstance(t, router, map[string]any{
195			"service_name": "svc", "instance_id": "unhealthy-fresh", "address": "c",
196			"healthy": false, "weight": 10, "heartbeat_at": at(9),
197		})
198		registerInstance(t, router, map[string]any{
199			"service_name": "svc", "instance_id": "newest", "address": "d",
200			"healthy": true, "weight": 5, "heartbeat_at": at(10),
201		})
202		registerInstance(t, router, map[string]any{
203			"service_name": "other", "instance_id": "must-not-appear",
204			"healthy": true, "weight": 100, "heartbeat_at": at(9),
205		})
206	
207		// The boundary is inclusive: evaluate 12:10 with timeout 10m puts the
208		// lost boundary at exactly 12:00, so the 12:00 heartbeat is still online.
209		target := "/api/v1/discover?service_name=svc&evaluate_at=" + at(10) + "&heartbeat_timeout=10m"
210		out := decodeBody(t, doRequest(t, router, http.MethodGet, target, nil))
211		ids := instanceIDs(t, out)
212		want := []string{"lost-old", "newest", "fresh"}
213		if len(ids) != len(want) {
214			t.Fatalf("boundary ids = %v, want %v", ids, want)
215		}
216		for i := range want {
217			if ids[i] != want[i] {
218				t.Fatalf("boundary ids = %v, want %v", ids, want)
219			}
220		}
221		// Nothing was strictly past the boundary: every record remains stored.
222		if list, err := st.ListInstances("svc"); err != nil || len(list) != 4 {
223			t.Fatalf("boundary query changed storage: %d rows err=%v", len(list), err)
224		}
225	
226		// Strictly past the boundary evicts and deletes: at 12:10:30 with 10m
227		// the boundary is 12:00:30, so the 12:00 record is lost.
228		evaluate := time.Date(2026, 10, 1, 12, 10, 30, 0, time.UTC).Format(time.RFC3339)
229		target = "/api/v1/discover?service_name=svc&evaluate_at=" + evaluate + "&heartbeat_timeout=10m"
230		out = decodeBody(t, doRequest(t, router, http.MethodGet, target, nil))
231		if ids := instanceIDs(t, out); len(ids) != 2 || ids[0] != "newest" || ids[1] != "fresh" {
232			t.Fatalf("after-loss ids = %v, want [newest fresh]", ids)
233		}
234		if _, found, _ := st.GetInstance("svc", "lost-old"); found {
235			t.Fatalf("lost record was not deleted")
236		}
237		// Unhealthy but fresh records stay stored; other services are untouched.
238		if _, found, _ := st.GetInstance("svc", "unhealthy-fresh"); !found {
239			t.Fatalf("unhealthy fresh record was removed")
240		}
241		if other, err := st.ListInstances("other"); err != nil || len(other) != 1 {
242			t.Fatalf("other service changed: %d rows err=%v", len(other), err)
243		}
244	}
