72	BEGIN SELECT RAISE(ABORT, 'simulated delete failure'); END`, quoted)
73		if _, err := db.Exec(statement); err != nil {
74			db.Close()
75			t.Fatalf("install trigger: %v", err)
76		}
77		return func() {
78			if _, err := db.Exec("DROP TRIGGER discover_test_fail_delete"); err != nil {
79				t.Fatalf("drop trigger: %v", err)
80			}
81			if err := db.Close(); err != nil {
82				t.Fatalf("close second connection: %v", err)
83			}
84		}
85	}
