147	func TestDiscoverLostCleanupIsAtomic(t *testing.T) {
148		for _, entry := range discoverEntries {
149			t.Run(entry.name, func(t *testing.T) {
150				dbPath := filepath.Join(t.TempDir(), "service.db")
151				st, err := store.Open(dbPath)
152				if err != nil {
153					t.Fatalf("open: %v", err)
154				}
155				t.Cleanup(func() { st.Close() })
156				router := NewRouter(st)
157				seedAtomicFixture(t, router)
158	
159				// The deletion of lost-b fails after the deletion of lost-a has
160				// already been executed inside the cleanup.
161				clear := failDeleteOf(t, dbPath, "lost-b")
162	
163				rec := doRequest(t, router, entry.method, entry.target, entry.body)
164				if rec.Code != http.StatusServiceUnavailable {
165					t.Fatalf("status = %d, want 503, body %s", rec.Code, rec.Body.String())
166				}
167				out := decodeBody(t, rec)
168				if len(out) != 1 {
169					t.Fatalf("error body must contain only the error object: %v", out)
170				}
171				errObj, ok := out["error"].(map[string]any)
172				if !ok {
173					t.Fatalf("missing error object: %v", out)
174				}
175				if errObj["code"] != "storage_unavailable" {
176					t.Fatalf("code = %v, want storage_unavailable", errObj["code"])
177				}
178				message, ok := errObj["message"].(string)
179				if !ok || message == "" {
180					t.Fatalf("message must be a non-empty string: %v", errObj)
181				}
182				for _, leak := range []string{"simulated delete failure", "sql", "goroutine", ".go"} {
183					if strings.Contains(strings.ToLower(message), leak) {
184						t.Fatalf("message leaks internals %q: %q", leak, message)
185					}
186				}
187				if _, present := out["instances"]; present {
188					t.Fatalf("failed cleanup must not return a candidate list: %v", out)
189				}
190	
191				// No deletion may have taken effect: every svc record is still
192				// stored with its full field set, and the other service is
193				// untouched.
194				expectRecords(t, router, atomicFixtureRecords())
195				other, err := st.ListInstances("other")
196				if err != nil || len(other) != 1 || other[0].InstanceID != "other-1" {
197					t.Fatalf("other service changed: %v err=%v", other, err)
198				}
199	
200				// With the failure cleared, the same request removes both lost
201				// records and returns the remaining healthy candidates.
202				clear()
203				rec = doRequest(t, router, entry.method, entry.target, entry.body)
204				if rec.Code != http.StatusOK {
205					t.Fatalf("retry status = %d, want 200, body %s", rec.Code, rec.Body.String())
206				}
207				out = decodeBody(t, rec)
208				if out["service_name"] != "svc" || out["evaluate_at"] != at(10) ||
209					out["heartbeat_timeout"] != float64(300) {
210					t.Fatalf("retry response metadata mismatch: %v", out)
211				}
212				if ids := instanceIDs(t, out); len(ids) != 2 || ids[0] != "fresh-high" || ids[1] != "fresh-low" {
213					t.Fatalf("retry ids = %v, want [fresh-high fresh-low]", ids)
214				}
215				expectRecords(t, router, map[string]wantRecord{
216					"fresh-high": {"10.0.0.3", 8003, true, 8, at(9)},
217					"fresh-low":  {"10.0.0.4", 8004, true, 5, at(9)},
218					"sick-fresh": {"10.0.0.5", 8005, false, 7, at(9)},
219				})
220				if other, err := st.ListInstances("other"); err != nil || len(other) != 1 {
221					t.Fatalf("other service changed by retry: %v err=%v", other, err)
222				}
223	
224				// Repeating the request yields the same candidates and changes
225				// nothing further.
226				rec = doRequest(t, router, entry.method, entry.target, entry.body)
227				if rec.Code != http.StatusOK {
228					t.Fatalf("repeat status = %d, want 200, body %s", rec.Code, rec.Body.String())
229				}
230				if ids := instanceIDs(t, decodeBody(t, rec)); len(ids) != 2 || ids[0] != "fresh-high" || ids[1] != "fresh-low" {
231					t.Fatalf("repeat ids = %v, want [fresh-high fresh-low]", ids)
232				}
233				expectRecords(t, router, map[string]wantRecord{
234					"fresh-high": {"10.0.0.3", 8003, true, 8, at(9)},
235					"fresh-low":  {"10.0.0.4", 8004, true, 5, at(9)},
236					"sick-fresh": {"10.0.0.5", 8005, false, 7, at(9)},
237				})
238			})
239		}
240	}
