242	func TestDiscoverStrictBoundarySurvivesFailedCleanup(t *testing.T) {
243		dbPath := filepath.Join(t.TempDir(), "service.db")
244		st, err := store.Open(dbPath)
245		if err != nil {
246			t.Fatalf("open: %v", err)
247		}
248		t.Cleanup(func() { st.Close() })
249		router := NewRouter(st)
250	
251		// edge sits exactly on the lost boundary at 12:05, lost sits strictly
252		// past it; the cleanup of lost is made to fail.
253		registerInstance(t, router, map[string]any{
254			"service_name": "svc", "instance_id": "edge", "healthy": true,
255			"weight": 2, "heartbeat_at": at(5),
256		})
257		registerInstance(t, router, map[string]any{
258			"service_name": "svc", "instance_id": "lost", "healthy": true,
259			"weight": 1, "heartbeat_at": at(0),
260		})
261		clear := failDeleteOf(t, dbPath, "lost")
262	
263		target := "/api/v1/services/svc/discover?evaluate_at=" + at(10) + "&heartbeat_timeout=5m"
264		rec := doRequest(t, router, http.MethodGet, target, nil)
265		if rec.Code != http.StatusServiceUnavailable {
266			t.Fatalf("status = %d, want 503, body %s", rec.Code, rec.Body.String())
267		}
268		// The boundary record must survive the failed cleanup exactly as stored.
269		if _, found, err := st.GetInstance("svc", "edge"); err != nil || !found {
270			t.Fatalf("boundary record lost: found=%v err=%v", found, err)
271		}
272		if _, found, err := st.GetInstance("svc", "lost"); err != nil || !found {
273			t.Fatalf("lost record deleted despite failed cleanup: found=%v err=%v", found, err)
274		}
275	
276		// Once the failure is cleared the boundary record is still online and
277		// only the strictly lost record is removed.
278		clear()
279		rec = doRequest(t, router, http.MethodGet, target, nil)
280		if rec.Code != http.StatusOK {
281			t.Fatalf("retry status = %d, want 200, body %s", rec.Code, rec.Body.String())
282		}
283		if ids := instanceIDs(t, decodeBody(t, rec)); len(ids) != 1 || ids[0] != "edge" {
284			t.Fatalf("retry ids = %v, want [edge]", ids)
285		}
286		if _, found, _ := st.GetInstance("svc", "edge"); !found {
287			t.Fatalf("boundary record deleted by retry")
288		}
289		if _, found, _ := st.GetInstance("svc", "lost"); found {
290			t.Fatalf("lost record not deleted by retry")
291		}
292	}
