294	func TestDiscoverRejectedParametersChangeNothing(t *testing.T) {
295		router, st := testRouter(t)
296		seedAtomicFixture(t, router)
297	
298		getTargets := []string{
299			"/api/v1/discover?service_name=&evaluate_at=" + at(10) + "&heartbeat_timeout=5m", // empty service name
300			"/api/v1/discover?service_name=svc&heartbeat_timeout=5m",                         // missing evaluate_at
301			"/api/v1/discover?service_name=svc&evaluate_at=not-a-time&heartbeat_timeout=5m",  // bad evaluate_at
302			"/api/v1/discover?service_name=svc&evaluate_at=" + at(10),                        // missing timeout
303			"/api/v1/discover?service_name=svc&evaluate_at=" + at(10) + "&heartbeat_timeout=0",
304			"/api/v1/discover?service_name=svc&evaluate_at=" + at(10) + "&heartbeat_timeout=-5s",
305			"/api/v1/discover?service_name=svc&evaluate_at=" + at(10) + "&heartbeat_timeout=abc",
306			"/api/v1/discover?service_name=svc&evaluate_at=" + at(8) + "&heartbeat_timeout=5m", // before a heartbeat
307		}
308		for _, target := range getTargets {
309			rec := doRequest(t, router, http.MethodGet, target, nil)
310			expectParameterError(t, rec)
311			if out := decodeBody(t, rec); len(out) != 1 {
312				t.Fatalf("%s: error body must contain only the error object: %v", target, out)
313			}
314		}
315	
316		// On the path entry the path service name always wins, so a conflicting
317		// or blank body service_name is ignored rather than rejected; blank-name
318		// rejection stays covered above through the param-style /api/v1/discover
319		// entry. Every remaining malformed field must still reject the request.
320		postBodies := []map[string]any{
321			{"service_name": "svc", "heartbeat_timeout": "5m"},
322			{"service_name": "svc", "evaluate_at": "soon", "heartbeat_timeout": "5m"},
323			{"service_name": "svc", "evaluate_at": at(10)},
324			{"service_name": "svc", "evaluate_at": at(10), "heartbeat_timeout": 0},
325			{"service_name": "svc", "evaluate_at": at(10), "heartbeat_timeout": -30},
326			{"service_name": "svc", "evaluate_at": at(10), "heartbeat_timeout": "abc"},
327			{"service_name": "svc", "evaluate_at": at(8), "heartbeat_timeout": "5m"},
328		}
329		for _, body := range postBodies {
330			rec := doRequest(t, router, http.MethodPost, "/api/v1/services/svc/discover", body)
331			expectParameterError(t, rec)
332			if out := decodeBody(t, rec); len(out) != 1 {
333				t.Fatalf("%v: error body must contain only the error object: %v", body, out)
334			}
335		}
336	
337		// No rejected request deleted or altered anything, including the two
338		// strictly lost records that a valid request would have removed.
339		expectRecords(t, router, atomicFixtureRecords())
340		if other, err := st.ListInstances("other"); err != nil || len(other) != 1 {
341			t.Fatalf("other service changed: %v err=%v", other, err)
342		}
343	}
