345	// TestDiscoverTimeoutBoundaryAcrossEntries pins the strict lost boundary on
346	// every discovery entry: evaluate_at exactly heartbeat_at + timeout keeps
347	// the record online, one second later evicts and deletes it.
348	func TestDiscoverTimeoutBoundaryAcrossEntries(t *testing.T) {
349		// One second past the boundary: heartbeat 12:05 + 5m < 12:10:01.
350		past := time.Date(2026, 10, 1, 12, 10, 1, 0, time.UTC).Format(time.RFC3339)
351		pastEntries := []struct {
352			method string
353			target string
354			body   any
355		}{
356			{http.MethodGet, "/api/v1/discover?service_name=svc&evaluate_at=" + past + "&heartbeat_timeout=5m", nil},
357			{http.MethodGet, "/api/v1/services/svc/discover?evaluate_at=" + past + "&heartbeat_timeout=5m", nil},
358			{http.MethodPost, "/api/v1/discover", map[string]any{
359				"service_name": "svc", "evaluate_at": past, "heartbeat_timeout": "5m"}},
360			{http.MethodPost, "/api/v1/services/svc/discover", map[string]any{
361				"evaluate_at": past, "heartbeat_timeout": 300}},
362		}
363		for index, entry := range discoverEntries {
364			t.Run(entry.name, func(t *testing.T) {
365				router, st := testRouter(t)
366				registerInstance(t, router, map[string]any{
367					"service_name": "svc", "instance_id": "edge", "healthy": true,
368					"weight": 1, "heartbeat_at": at(5),
369				})
370	
371				// Exactly on the boundary: online, returned, kept.
372				rec := doRequest(t, router, entry.method, entry.target, entry.body)
373				if rec.Code != http.StatusOK {
374					t.Fatalf("boundary status = %d, body %s", rec.Code, rec.Body.String())
375				}
376				if ids := instanceIDs(t, decodeBody(t, rec)); len(ids) != 1 || ids[0] != "edge" {
377					t.Fatalf("boundary ids = %v, want [edge]", ids)
378				}
379				if _, found, _ := st.GetInstance("svc", "edge"); !found {
380					t.Fatalf("boundary record deleted")
381				}
382	
383				// Strictly past the boundary: lost, excluded, deleted.
384				pastEntry := pastEntries[index]
385				rec = doRequest(t, router, pastEntry.method, pastEntry.target, pastEntry.body)
386				if rec.Code != http.StatusOK {
387					t.Fatalf("past-boundary status = %d, body %s", rec.Code, rec.Body.String())
388				}
389				if ids := instanceIDs(t, decodeBody(t, rec)); len(ids) != 0 {
390					t.Fatalf("past-boundary ids = %v, want []", ids)
391				}
392				if _, found, _ := st.GetInstance("svc", "edge"); found {
393					t.Fatalf("strictly lost record not deleted")
394				}
395			})
396		}
397	}
