		t.Fatalf("%s retry: evaluate_at = %v, want %s", entry, out["evaluate_at"], at(10))
	}
	if out["heartbeat_timeout"].(float64) != 300 {
		t.Fatalf("%s retry: heartbeat_timeout = %v, want 300", entry, out["heartbeat_timeout"])
	}
	if out["removed"] != float64(3) {
		t.Fatalf("%s retry: removed = %v, want 3", entry, out["removed"])
	}
	removed := out["instances"].([]any)
	if len(removed) != 3 {
		t.Fatalf("%s retry: instances len = %d, want 3", entry, len(removed))
	}
	wantRemoved := []string{"alpha/lost-a", "beta/lost-b", "gamma/lost-g"}
