	// surviving record is on the boundary or unhealthy but fresh.
	rec = doRequest(t, router, http.MethodPost, target, nil)
	if rec.Code != http.StatusOK {
		t.Fatalf("%s repeat: status %d body %s", entry, rec.Code, rec.Body.String())
	}
